#include <bits/stdc++.h>
using namespace std;

const int MOD = 998244353;

long long mod_pow(long long a, long long e = MOD - 2) {
    long long r = 1;
    while (e) {
        if (e & 1) r = r * a % MOD;
        a = a * a % MOD;
        e >>= 1;
    }
    return r;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int p, s, r;
    if(!(cin >> p >> s >> r)) return 0;

    vector<long long> fact(10001), inv_fact(10001);
    fact[0] = 1;
    for (int i = 1; i <= 10000; ++i) fact[i] = fact[i-1] * i % MOD;
    inv_fact[10000] = mod_pow(fact[10000]);
    for (int i = 10000; i >= 1; --i) inv_fact[i-1] = inv_fact[i] * i % MOD;

    auto C = [&](int n, int k) -> long long {
        if (k < 0 || k > n) return 0;
        return fact[n] * inv_fact[k] % MOD * inv_fact[n-k] % MOD;
    };

    // Total number of states
    long long total = C(s - r + p - 1, p - 1);

    long long win = 0;
    // Iterate Hasan's score x
    for (int x = r; x <= s; ++x) {
        int rem = s - x;
        if (rem < 0) break;
        int max_per_other = x;
        if (max_per_other * (p - 1) < rem) {
            // Even if all others score max, sum < rem -> no valid distributions
            continue;
        }
        // Inclusion-exclusion for others: each of p-1 players has score in [0, x]
        long long ways = 0;
        for (int k = 0; k <= p - 1; ++k) {
            long long sum = rem - 1LL * k * (x + 1);
            if (sum < 0) break;
            long long term = C(sum + p - 2, p - 2);
            if (k % 2 == 0) ways = (ways + C(p - 1, k) * term) % MOD;
            else ways = (ways - C(p - 1, k) * term) % MOD;
        }
        if (ways < 0) ways += MOD;

        // Now among these distributions, calculate probability Hasan wins
        // We need to count for each t (number of other players who also scored x)
        // But easier: sum over t=0..p-1 of [1/(t+1) * ways where exactly t others scored x]

        // Number of ways where exactly t other players scored x:
        // Choose t players: C(p-1, t)
        // They score x, sum contributed = t*x
        // Remaining sum for other p-1-t players: rem - t*x
        // They must score in [0, x-1] (since exactly t scored x)
        for (int t = 0; t <= p - 1; ++t) {
            long long sum_other = rem - 1LL * t * x;
            if (sum_other < 0) break;
            int m = p - 1 - t;
            if (m < 0) continue;
            // Max allowed score for remaining players: x-1
            if (x == 0) {
                // If x==0, then x-1 is -1, but scores >=0. So only valid if sum_other==0 and m>=0
                if (sum_other == 0) {
                    long long ways_t = C(p - 1, t);
                    long long prob = mod_pow(t + 1);
                    win = (win + ways_t * prob) % MOD;
                }
                continue;
            }
            int max_score = x - 1;
            if (1LL * max_score * m < sum_other) continue;
            // Inclusion-exclusion for remaining m players with scores in [0, max_score]
            long long ways_rem = 0;
            for (int k = 0; k <= m; ++k) {
                long long sum = sum_other - 1LL * k * (max_score + 1);
                if (sum < 0) break;
                long long term = C(sum + m - 1, m - 1);
                if (k % 2 == 0) ways_rem = (ways_rem + C(m, k) * term) % MOD;
                else ways_rem = (ways_rem - C(m, k) * term) % MOD;
            }
            if (ways_rem < 0) ways_rem += MOD;

            long long ways_t = C(p - 1, t) * ways_rem % MOD;
            long long prob = mod_pow(t + 1);
            win = (win + ways_t * prob) % MOD;
        }
    }

    long long ans = win * mod_pow(total) % MOD;
    cout << ans << "\n";
    return 0;
}
