        if (e & 1) r = r * a % MOD;
        a = a * a % MOD;
        e >>= 1;
    }
    return r;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int p, s, r;
    cin >> p >> s >> r;

    // Combination table up to 6000
    const int MAXN = 6000;
    vector<vector<int>> C(MAXN + 1, vector<int>(MAXN + 1, 0));
    for (int i = 0; i <= MAXN; ++i) {
        C[i][0] = C[i][i] = 1;
        for (int j = 1; j < i; ++j) {
            C[i][j] = (C[i-1][j-1] + C[i-1][j]) % MOD;
        }
    }

    auto nCr = [&](int n, int k) -> int {
        if (n < 0 || k < 0 || k > n) return 0;
        return C[n][k];
    };

    // number of non-negative integer solutions to x_1 + ... + x_k = n
    auto stars_bars = [&](int n, int k) -> int {
        if (k == 0) return (n == 0) ? 1 : 0;
        if (n < 0) return 0;
        return nCr(n + k - 1, k - 1);
    };

    // number of ways to distribute sum S among K variables each in [0, M]
    auto ways_bounded = [&](int S, int K, int M) -> int {
        if (K == 0) return (S == 0) ? 1 : 0;
        if (S < 0) return 0;
        if (M < 0) return 0;
        long long res = 0;
        for (int i = 0; i <= K; ++i) {
            long long rem = S - 1LL * i * (M + 1);
            if (rem < 0) break;
            int term = stars_bars(rem, K);
            if (i % 2 == 1) {
                res = (res - 1LL * nCr(K, i) * term) % MOD;
            } else {
                res = (res + 1LL * nCr(K, i) * term) % MOD;
            }
        }
        return (res % MOD + MOD) % MOD;
    };

    // total number of states
    int total_states = stars_bars(s - r, p);

    long long favorable = 0;
    for (int x = r; x <= s; ++x) {
        int rem = s - x;
        if (rem < 0) break;
        int K = p - 1;
        if (K == 0) {
            // only Hasan: he always wins
            favorable = (favorable + 1) % MOD;
            continue;
        }
        int ways_all_le = ways_bounded(rem, K, x);
        int ways_all_le_x1 = ways_bounded(rem, K, x - 1);
        int ways_max_eq_x = (ways_all_le - ways_all_le_x1 + MOD) % MOD;

        // favorable contribution: cases where all others <= x-1 (strictly less than x)
        long long contrib = ways_all_le_x1;

        // cases where some others equal x
        for (int k = 1; k <= K; ++k) {
            int rem_k = rem - k * x;
            if (rem_k < 0) break;
            int choose = nCr(K, k);
            int ways_others = ways_bounded(rem_k, K - k, x - 1);
            long long prob = 1LL * choose * ways_others % MOD * modpow(k + 1) % MOD;
            contrib = (contrib + prob) % MOD;
        }

        favorable = (favorable + contrib) % MOD;
    }

    int ans = favorable * modpow(total_states) % MOD;
    cout << ans << "\n";
    return 0;
}
