int modpow(int a, int e = MOD - 2) {
    long long res = 1, cur = a;
    while (e) {
        if (e & 1) res = res * cur % MOD;
        cur = cur * cur % MOD;
        e >>= 1;
    }
    return (int)res;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int p, s, r;
    if (!(cin >> p >> s >> r)) return 0;

    int maxN = 6000;
    vector<int> fact(maxN + 1), invfact(maxN + 1);
    fact[0] = 1;
    for (int i = 1; i <= maxN; ++i) fact[i] = (long long)fact[i - 1] * i % MOD;
    invfact[maxN] = modpow(fact[maxN]);
    for (int i = maxN; i > 0; --i) invfact[i - 1] = (long long)invfact[i] * i % MOD;

    auto C = [&](int n, int k) -> int {
        if (k < 0 || k > n) return 0;
        return (long long)fact[n] * invfact[k] % MOD * invfact[n - k] % MOD;
    };

    // ways(n, k, ub): number of ways to write n as sum of k non-negative integers each <= ub
    auto ways = [&](int n, int k, int ub) -> int {
        if (n < 0) return 0;
        if (k == 0) return n == 0 ? 1 : 0;
        if (ub < 0) return 0;
        if ((long long)k * ub < n) return 0;
        int res = 0;
        int max_i = min(k, n / (ub + 1));
        for (int i = 0; i <= max_i; ++i) {
            int term = (long long)C(k, i) * C(n - i * (ub + 1) + k - 1, k - 1) % MOD;
            if (i % 2 == 0) {
                res += term;
                if (res >= MOD) res -= MOD;
            } else {
                res -= term;
                if (res < 0) res += MOD;
            }
        }
        return res;
    };

    int q = p - 1;

    // total number of valid states
    long long total = 0;
    for (int a1 = r; a1 <= s; ++a1) {
        int rem = s - a1;
        total += ways(rem, q, s); // ub = s is effectively unbounded for non-negative
        if (total >= MOD) total -= MOD;
    }
    total %= MOD;

    //avorable outcomes
    long long favorable = 0;
    for (int a1 = r; a1 <= s; ++a1) {
        int rem = s - a1;
        // case 1: win outright
        favorable += ways(rem, q, a1 - 1);
        if (favorable >= MOD) favorable -= MOD;

        // case 2: tie for top with t other players (t >= 1)
        for (int t = 1; t <= q; ++t) {
            int sum_tied = t * a1;
            if (sum_tied > rem) break;
            int rem2 = rem - sum_tied;
            int k = q - t;
            int w = ways(rem2, k, a1 - 1);
            if (w == 0) continue;
            int choose_t = C(q, t);
            int inv_t1 = modpow(t + 1);
            long long add = (long long)choose_t * w % MOD * inv_t1 % MOD;
            favorable += add;
            if (favorable >= MOD) favorable -= MOD;
        }
    }
    favorable %= MOD;

    int ans = (long long)favorable * modpow(total) % MOD;
    cout << ans << '\n';
    return 0;
}
