#include <bits/stdc++.h>
using namespace std;

const int MOD = 998244353;
const int MAXN = 105;
const int MAXS = 5005;

int p, s, r;
vector<int> fact, inv_fact;
int dp[MAXN][MAXS];
int C[MAXS][MAXN];

int modpow(int a, int e = MOD - 2) {
    long long res = 1, cur = a;
    while (e) {
        if (e & 1) res = res * cur % MOD;
        cur = cur * cur % MOD;
        e >>= 1;
    }
    return (int)res;
}

int nCr(int n, int k) {
    if (k < 0 || k > n) return 0;
    return (long long)fact[n] * inv_fact[k] % MOD * inv_fact[n - k] % MOD;
}

// Number of ways to distribute sum 'sum' among 'n' players, each >= 0.
// Standard stars and bars: C(sum + n - 1, n - 1)
int ways(int n, int sum) {
    if (n == 0) return sum == 0;
    if (sum < 0) return 0;
    return nCr(sum + n - 1, n - 1);
}

// Number of ways to distribute sum 'sum' among 'n' players, each in [0, ub].
int ways_ub(int n, int sum, int ub) {
    if (n == 0) return sum == 0;
    if (sum < 0) return 0;
    if (ub < 0) return 0;
    // Inclusion-Exclusion
    // sum_{k=0}^n (-1)^k * C(n, k) * C(sum - k*(ub+1) + n - 1, n - 1)
    long long res = 0;
    for (int k = 0; k <= n; ++k) {
        int rem = sum - k * (ub + 1);
        if (rem < 0) break;
        int term = (long long)nCr(n, k) * nCr(rem + n - 1, n - 1) % MOD;
        if (k % 2 == 0) res = (res + term) % MOD;
        else res = (res - term + MOD) % MOD;
    }
    return (int)res;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> p >> s >> r;

    // Precompute factorials up to s + p
    int MAXF = s + p + 5;
    fact.resize(MAXF);
    inv_fact.resize(MAXF);
    fact[0] = 1;
    for (int i = 1; i < MAXF; ++i) fact[i] = (long long)fact[i - 1] * i % MOD;
    inv_fact[MAXF - 1] = modpow(fact[MAXF - 1]);
    for (int i = MAXF - 2; i >= 0; --i) inv_fact[i] = (long long)inv_fact[i + 1] * (i + 1) % MOD;

    // Total number of valid states: a_1 >= r, sum = s
    // Let a_1 = x, x from r to s.
    // Others sum to s - x, p-1 players >= 0.
    long long total_states = 0;
    for (int x = r; x <= s; ++x) {
        total_states = (total_states + ways(p - 1, s - x)) % MOD;
    }

    // Winning states:
    // Hasan wins if his score x is strictly greater than all others,
    // OR x is tied with k other players (k >= 1) and he is chosen as winner (prob 1/(k+1)).
    // Sum over x from r to s.
    // For a fixed x, sum over k = 0 to p-1 (number of other players scoring exactly x).
    // If k=0: all others < x. Ways: ways_ub(p-1, s-x, x-1). Probability contribution: 1.
    // If k>=1: choose k players to have score x. Remaining p-1-k players have score < x, sum = s - x - k*x = s - (k+1)x.
    // Ways: C(p-1, k) * ways_ub(p-1-k, s - (k+1)*x, x-1).
    // Probability contribution: 1/(k+1).

    long long winning_states = 0;
    for (int x = r; x <= s; ++x) {
        // Case k = 0
        int w0 = ways_ub(p - 1, s - x, x - 1);
        winning_states = (winning_states + w0) % MOD;

        // Cases k >= 1
        for (int k = 1; k <= p - 1; ++k) {
            int rem_sum = s - (k + 1) * x;
            if (rem_sum < 0) break;
            int w_ub = ways_ub(p - 1 - k, rem_sum, x - 1);
            if (w_ub == 0) continue;
            int choose = nCr(p - 1, k);
            long long term = (long long)choose * w_ub % MOD;
            term = term * modpow(k + 1) % MOD;
            winning_states = (winning_states + term) % MOD;
        }
    }

    int ans = (long long)winning_states * modpow(total_states) % MOD;
    cout << ans << "\n";
    return 0;
}
