#include <bits/stdc++.h>
using namespace std;

const int MOD = 998244353;
const int MAXP = 100;
const int MAXS = 5000;

long long modpow(long long a, long long e = MOD - 2) {
    long long r = 1;
    while (e) {
        if (e & 1) r = r * a % MOD;
        a = a * a % MOD;
        e >>= 1;
    }
    return r;
}

long long fact[MAXS + MAXP + 10];
long long invFact[MAXS + MAXP + 10];

long long nCr(int n, int r) {
    if (r < 0 || r > n) return 0;
    return fact[n] * invFact[r] % MOD * invFact[n - r] % MOD;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int p, s, r;
    cin >> p >> s >> r;

    // Precompute factorials
    int maxN = s + p + 5;
    fact[0] = 1;
    for (int i = 1; i <= maxN; i++) fact[i] = fact[i - 1] * i % MOD;
    invFact[maxN] = modpow(fact[maxN]);
    for (int i = maxN - 1; i >= 0; i--) invFact[i] = invFact[i + 1] * (i + 1) % MOD;

    // Total number of valid states (a1 >= r, sum = s)
    long long total_states = nCr(s - r + p - 1, p - 1);

    if (total_states == 0) { // Should not happen given constraints p>=1, r<=s
        cout << 0 << "\n";
        return 0;
    }

    long long favorable = 0;
    // iterate over Hasan's score x >= r
    for (int x = r; x <= s; x++) {
        int remSum = s - x;
        if (remSum < 0) break;
        // iterate over number of other players k who also scored x (ties with Hasan)
        // k can be from 0 to min(p-1, remSum/x)
        int maxK = p - 1;
        if (x > 0) maxK = min(maxK, remSum / x);

        for (int k = 0; k <= maxK; k++) {
            int sumOthers = remSum - k * x;
            int playersOthers = p - 1 - k;
            // We need sum of scores of playersOthers to be sumOthers, with each score <= x-1
            // Number of ways to distribute sumOthers into playersOthers with 0 <= score <= x-1
            // Using inclusion-exclusion:
            long long waysOthers = 0;
            for (int i = 0; i <= playersOthers; i++) {
                // i players get >= x (violate the <= x-1 constraint)
                int rem = sumOthers - i * x;
                if (rem < 0) break;
                // Distribute rem among playersOthers players (no upper bound)
                long long waysRem = nCr(rem + playersOthers - 1, playersOthers - 1);
                long long choose = nCr(playersOthers, i);
                long long term = choose * waysRem % MOD;
                if (i % 2 == 0) waysOthers = (waysOthers + term) % MOD;
                else waysOthers = (waysOthers - term + MOD) % MOD;
            }
            // Choose which k of the p-1 opponents scored exactly x
            long long chooseK = nCr(p - 1, k);
            // Probability Hasan wins = 1/(k+1)
            long long probWin = modpow(k + 1);
            long long add = chooseK * waysOthers % MOD * probWin % MOD;
            favorable = (favorable + add) % MOD;
        }
    }

    long long ans = favorable * modpow(total_states) % MOD;
    cout << ans << "\n";
    return 0;
}
